// Mermaid icon packs, read from a local directory at start-up (never fetched at render time, so the
// renderer's "block all network" lockdown keeps working). A pack is one `<prefix>.json` file:
// Iconify JSON plus an optional `sirenia` object with the pack's label, owner, terms link and the
// notice text that travels with exports. Zero, one or many packs may be installed. The Google Cloud
// pack is generated by scripts/build-gcp-icon-pack.mjs (see icons/gcp/README.md).
const fs = require('node:fs');
const path = require('node:path');

const { PRODUCT_NAME } = require('./branding');
const { PREFIX, readPack } = require('./packFile');

const DEFAULT_PACKS_DIR = path.join(__dirname, '..', 'packs');
const PACKS_DIR = process.env.PACKS_DIR ? path.resolve(process.env.PACKS_DIR) : DEFAULT_PACKS_DIR;
// Pack recipes (`<dir>/<name>/mapping.json`, the `packs` command's input) are only a hint source:
// they let the API say "install pack X" instead of rendering Mermaid's "?" icon. Default: the
// repository's `icons/` directory when it exists next to `backend/`; the hosted backend image
// contains only `backend/`, so there it is simply absent.
const DEFAULT_RECIPES_DIR = path.join(__dirname, '..', '..', 'icons');
const PACK_RECIPES_DIR = process.env.PACK_RECIPES_DIR
  ? path.resolve(process.env.PACK_RECIPES_DIR)
  : (fs.existsSync(DEFAULT_RECIPES_DIR) ? DEFAULT_RECIPES_DIR : null);
const INDEX_FILE = 'index.json'; // the editor's index; generated next to the packs, not a pack

/** Every `*.json` in `dir` except the index, sorted. A missing directory means no packs. */
function packFiles(dir) {
  let names;
  try {
    names = fs.readdirSync(dir);
  } catch (e) {
    if (e.code === 'ENOENT') return [];
    throw e;
  }
  return names
    .filter((n) => n.endsWith('.json') && n !== INDEX_FILE && !n.startsWith('.'))
    .sort()
    .map((n) => path.join(dir, n))
    .filter((f) => fs.statSync(f).isFile());
}

/**
 * prefix → label for every recipe under `recipesDir` (each `<name>/mapping.json` with a `prefix` and a
 * `pack.label`). A hint, not a dependency: a missing directory means no recipes, and anything
 * unreadable is logged once and skipped.
 */
function readRecipes(recipesDir) {
  const recipes = new Map();
  if (!recipesDir) return recipes;
  let names = [];
  try {
    names = fs.readdirSync(recipesDir).sort();
  } catch (e) {
    if (e.code !== 'ENOENT') console.warn(`Pack recipes ignored (${recipesDir}): ${e.message}`);
    return recipes;
  }
  for (const name of names) {
    const file = path.join(recipesDir, name, 'mapping.json');
    try {
      const mapping = JSON.parse(fs.readFileSync(file, 'utf8'));
      const label = mapping?.pack?.label;
      if (typeof mapping?.prefix === 'string' && PREFIX.test(mapping.prefix) && typeof label === 'string' && label.trim()) {
        recipes.set(mapping.prefix, label);
      }
    } catch (e) {
      if (e.code !== 'ENOENT' && e.code !== 'ENOTDIR') console.warn(`Pack recipe ignored (${file}): ${e.message}`);
    }
  }
  return recipes;
}

const escapeRegExp = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

/**
 * Load every pack in `dir` and return the icon API for them. Pure apart from reading `dir`, so tests
 * can load fixture directories. `productName` is written into the export notice. `recipesDir` is
 * optional (see readRecipes) and only feeds findMissingPacks.
 */
function loadPacks(dir, productName, recipesDir = null) {
  const packs = packFiles(dir).map(readPack);
  const seen = new Set();
  for (const p of packs) {
    if (seen.has(p.prefix)) throw new Error(`Invalid icon pack directory ${dir}: prefix "${p.prefix}" is used twice`);
    seen.add(p.prefix);
  }

  // prefix → every resolvable name (icons + aliases)
  const knownIcons = new Map(packs.map((p) => [p.prefix, new Set([...Object.keys(p.icons), ...Object.keys(p.aliases || {})])]));

  // The render page gets the Iconify part only. JSON.stringify output is valid JS, and '<' is
  // escaped so the payload stays inert even if it were ever placed via innerHTML. Each pack is
  // serialized once, here; a render page gets only the packs its diagram refers to.
  const pageJson = new Map(packs.map((p) => {
    const copy = { ...p };
    delete copy.sirenia;
    return [p.prefix, JSON.stringify(copy)
      .replace(/</g, '\\u003c')
      // U+2028/U+2029 are line terminators in JS source but not in JSON; escape them too.
      .replace(/[\u2028\u2029]/g, (c) => `\\u${c.charCodeAt(0).toString(16)}`)];
  }));
  /** The page script that registers the packs named in `prefixes` (unknown prefixes are ignored). */
  const iconPacksScript = (prefixes) => {
    const wanted = new Set(prefixes);
    return `window.__ICON_PACKS__=[${packs.filter((p) => wanted.has(p.prefix)).map((p) => pageJson.get(p.prefix)).join(',')}];`;
  };
  const script = iconPacksScript(packs.map((p) => p.prefix));

  // `prefix:name` reference pattern. Kept as a SOURCE string: a shared /g RegExp is stateful
  // (lastIndex survives across calls and is inherited by matchAll clones), which silently skips
  // matches on later requests. Each caller builds its own instance. With no packs there is no
  // pattern at all: an empty alternation would match every `:name`.
  const refSource = packs.length
    ? `\\b(${packs.map((p) => escapeRegExp(p.prefix)).join('|')}):([A-Za-z0-9_-]+)`
    : null;
  const refs = (code) => (refSource ? String(code).matchAll(new RegExp(refSource, 'g')) : []);

  // Export notice per pack: the pack's own sentence(s) plus the application's independence sentence.
  const notices = new Map();
  for (const p of packs) {
    const owner = p.sirenia?.owner;
    const text = p.sirenia?.notice?.export;
    if (owner && text) {
      notices.set(p.prefix, `${text} Generated with ${productName}, an independent product not affiliated with, sponsored by, or endorsed by ${owner}.`);
    }
  }

  /**
   * Return `prefix:name` references to an installed pack that do not resolve, so the API can answer
   * 400 with the offending names instead of silently rendering Mermaid's "?" placeholder icon.
   * Scope is deliberately narrow: only installed prefixes; Mermaid's built-in architecture icons
   * (cloud, database, …) and other prefixes are left to Mermaid. References inside labels count too.
   */
  function findUnknownIcons(code) {
    const unknown = new Set();
    for (const m of refs(code)) {
      if (!knownIcons.get(m[1]).has(m[2])) unknown.add(`${m[1]}:${m[2]}`);
    }
    return [...unknown];
  }

  // Recipes whose pack is NOT installed: prefix → label. Same reference pattern as `refSource`.
  const missing = new Map([...readRecipes(recipesDir)].filter(([prefix]) => !knownIcons.has(prefix)));
  const missingSource = missing.size
    ? `\\b(${[...missing.keys()].map(escapeRegExp).join('|')}):([A-Za-z0-9_-]+)`
    : null;

  /**
   * Packs the diagram references that have a recipe but are not installed, as `{ prefix, label }` in
   * recipe order. Same reference pattern (and the same deliberate "also inside labels" scope) as
   * findUnknownIcons; empty when there are no recipes.
   */
  function findMissingPacks(code) {
    if (!missingSource) return [];
    const used = new Set();
    for (const m of String(code).matchAll(new RegExp(missingSource, 'g'))) used.add(m[1]);
    return [...missing].filter(([prefix]) => used.has(prefix)).map(([prefix, label]) => ({ prefix, label }));
  }

  // Which packs a render page needs. Deliberately wider than packsUsedBy: Mermaid also resolves
  // `gcp-cloud-run` as `gcp:cloud-run`, so a prefix followed by ":" or "-" anywhere (any case)
  // counts, and each prefix is looked for on its own (`gcp-legacy:x` names both gcp and gcp-legacy).
  // A pack loaded for nothing costs time only; a pack left out would draw Mermaid's "?" icon.
  const renderPatterns = packs.map((p) => [p.prefix, new RegExp(`(?<![A-Za-z0-9_-])${escapeRegExp(p.prefix)}[:-]`, 'i')]);
  /** Prefixes of the installed packs a render of `code` may need, in pack order. */
  function packsForRender(code) {
    const text = String(code);
    return renderPatterns.filter(([, re]) => re.test(text)).map(([prefix]) => prefix);
  }

  // Mermaid also draws `gcp-cloud-run` (a dash in place of the colon) with the pack's icon. That
  // form counts as a use when the name is one the pack has, so the export still carries the notice.
  // Kept as source strings for the same reason as `refSource`.
  const dashSources = packs.map((p) => [p.prefix, `(?<![A-Za-z0-9_:-])${escapeRegExp(p.prefix)}-([A-Za-z0-9_-]+)`]);

  /**
   * Prefixes of installed packs whose icons the diagram uses (`gcp:cloud-run`, or `gcp-cloud-run`
   * when the pack has that icon), in pack order.
   */
  function packsUsedBy(code) {
    const text = String(code);
    const used = new Set();
    for (const m of refs(text)) used.add(m[1]);
    for (const [prefix, source] of dashSources) {
      if (used.has(prefix)) continue;
      for (const m of text.matchAll(new RegExp(source, 'g'))) {
        if (knownIcons.get(prefix).has(m[1])) { used.add(prefix); break; }
      }
    }
    return packs.map((p) => p.prefix).filter((prefix) => used.has(prefix));
  }

  /**
   * Notice written into an export that uses these packs (PNG iTXt "Disclaimer" / SVG <metadata>), so
   * it travels with the artwork: the notices of the packs that have one, in pack order, joined with
   * a space. null when none of them has a notice.
   */
  function attributionNotice(prefixes) {
    const wanted = new Set(prefixes);
    const texts = packs.filter((p) => wanted.has(p.prefix) && notices.has(p.prefix)).map((p) => notices.get(p.prefix));
    return texts.length ? texts.join(' ') : null;
  }

  return {
    ICON_PACKS: packs, ICON_PACKS_SCRIPT: script, KNOWN_ICONS: knownIcons,
    iconPacksScript, packsForRender, findUnknownIcons, findMissingPacks, packsUsedBy, attributionNotice,
  };
}

module.exports = { PACKS_DIR, PACK_RECIPES_DIR, loadPacks, ...loadPacks(PACKS_DIR, PRODUCT_NAME, PACK_RECIPES_DIR) };
